package org.freecad.mobilelab;
import java.util.*;
/** Exact rational open-uniform B-spline evaluation and XY drafting assists. */
final class SketchMath {
 static double[] nurbs(List<double[]> poles,double t){int count=poles.size(),degree=Math.min(3,count-1);if(count<2||count>64||!Double.isFinite(t)||t<0||t>1)throw new IllegalArgumentException("Invalid NURBS preview");double[] knots=new double[count+degree+1];for(int i=0;i<knots.length;i++)knots[i]=i<=degree?0:i>=count?1:(double)(i-degree)/(count-degree);int span=degree;if(t==1)span=count-1;else while(span<count-1&&t>=knots[span+1])span++;double[][] d=new double[degree+1][4];for(int j=0;j<=degree;j++){double[] p=poles.get(span-degree+j);if(p.length!=4||p[3]<=0||!Double.isFinite(p[3]))throw new IllegalArgumentException("Invalid control point");for(int k=0;k<3;k++)d[j][k]=p[k]*p[3];d[j][3]=p[3];}for(int r=1;r<=degree;r++)for(int j=degree;j>=r;j--){int i=span-degree+j;double alpha=(t-knots[i])/(knots[i+degree-r+1]-knots[i]);for(int k=0;k<4;k++)d[j][k]=(1-alpha)*d[j-1][k]+alpha*d[j][k];}return new double[]{d[degree][0]/d[degree][3],d[degree][1]/d[degree][3],d[degree][2]/d[degree][3]};}
 static final class Snap {final double x,y;final String kind;Snap(double x,double y,String kind){this.x=x;this.y=y;this.kind=kind;}}
 static Snap snap(double x,double y,double grid,double tolerance,List<double[]> points,int excluded,boolean objectSnap,boolean ortho){if(!Double.isFinite(x)||!Double.isFinite(y)||!Double.isFinite(grid)||grid<.001||grid>100||!Double.isFinite(tolerance)||tolerance<=0)throw new IllegalArgumentException("Invalid sketch snapping values");double best=tolerance*tolerance;Snap result=new Snap(Math.rint(x/grid)*grid,Math.rint(y/grid)*grid,"grid");if(objectSnap){for(int i=0;i<points.size();i++)if(i!=excluded){double[] p=points.get(i);double d=(p[0]-x)*(p[0]-x)+(p[1]-y)*(p[1]-y);if(d<best){best=d;result=new Snap(p[0],p[1],"point");}}for(int i=1;i<points.size();i++)if(i!=excluded&&i-1!=excluded){double[] p=points.get(i-1),q=points.get(i);double px=(p[0]+q[0])/2,py=(p[1]+q[1])/2,d=(px-x)*(px-x)+(py-y)*(py-y);if(d<best){best=d;result=new Snap(px,py,"midpoint");}}for(int a=1;a<points.size();a++)for(int b=a+2;b<points.size();b++)if(a!=excluded&&a-1!=excluded&&b!=excluded&&b-1!=excluded){double[] p=points.get(a-1),q=points.get(a),r=points.get(b-1),s=points.get(b);double dx=q[0]-p[0],dy=q[1]-p[1],ex=s[0]-r[0],ey=s[1]-r[1],den=dx*ey-dy*ex;if(Math.abs(den)<1e-10)continue;double tx=r[0]-p[0],ty=r[1]-p[1],u=(tx*ey-ty*ex)/den,v=(tx*dy-ty*dx)/den;if(u<0||u>1||v<0||v>1)continue;double px=p[0]+u*dx,py=p[1]+u*dy,d=(px-x)*(px-x)+(py-y)*(py-y);if(d<best){best=d;result=new Snap(px,py,"intersection");}}}if(ortho&&result.kind.equals("grid")&&!points.isEmpty()){int index=excluded>=0?Math.max(0,excluded-1):points.size()-1;double[] p=points.get(index);result=Math.abs(result.x-p[0])>Math.abs(result.y-p[1])?new Snap(result.x,p[1],"horizontal assist"):new Snap(p[0],result.y,"vertical assist");}if(Math.abs(result.x)>10000||Math.abs(result.y)>10000)throw new IllegalArgumentException("Sketch exceeds 10,000 mm");return result;}
}
